class Solution:
    def maxProfit(self, prices: list[int]) -> int:
        min_price = 10**9  # large initial value
        max_profit = 0
        for price in prices:
            if price < min_price:
                min_price = price
            else:
                profit = price - min_price
                if profit > max_profit:
                    max_profit = profit
        return max_profit

